#!/usr/bin/env node
'use strict';

// Extract initialized memory values from an ELF binary by simulating how the
// OS loader maps it: every PT_LOAD segment's bytes are placed at their virtual
// address (file bytes for [0,filesz), zero-filled for [filesz,memsz) == .bss),
// then each 4-byte little-endian word at a 4-byte-aligned address inside a
// mapped segment is reported as address -> unsigned 32-bit integer.

const fs = require('fs');

function readU16(buf, off, le) {
  return le ? buf.readUInt16LE(off) : buf.readUInt16BE(off);
}
function readU32(buf, off, le) {
  // >>>0 keeps it an unsigned 32-bit integer
  return (le ? buf.readUInt32LE(off) : buf.readUInt32BE(off)) >>> 0;
}
// Read a 64-bit little/big-endian value as a JS Number. Virtual addresses here
// are far below 2^53 so this is exact.
function readU64(buf, off, le) {
  const lo = readU32(buf, off, le);
  const hi = readU32(buf, off + 4, le);
  return hi * 0x100000000 + lo;
}

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf-binary>\n');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);

  const out = {};

  // Minimal ELF sanity check.
  if (buf.length < 64 || buf[0] !== 0x7f || buf[1] !== 0x45 ||
      buf[2] !== 0x4c || buf[3] !== 0x46) {
    process.stdout.write(JSON.stringify(out) + '\n');
    return;
  }

  const eiClass = buf[4]; // 1 = ELF32, 2 = ELF64
  const eiData = buf[5];  // 1 = little-endian, 2 = big-endian
  const le = (eiData !== 2);
  const is64 = (eiClass === 2);

  let e_phoff, e_phentsize, e_phnum;
  if (is64) {
    e_phoff = readU64(buf, 32, le);
    e_phentsize = readU16(buf, 54, le);
    e_phnum = readU16(buf, 56, le);
  } else {
    e_phoff = readU32(buf, 28, le);
    e_phentsize = readU16(buf, 42, le);
    e_phnum = readU16(buf, 44, le);
  }

  // Collect PT_LOAD (type 1) segments.
  const segs = [];
  for (let i = 0; i < e_phnum; i++) {
    const base = e_phoff + i * e_phentsize;
    let p_type, p_offset, p_vaddr, p_filesz, p_memsz;
    if (is64) {
      p_type = readU32(buf, base, le);
      p_offset = readU64(buf, base + 8, le);
      p_vaddr = readU64(buf, base + 16, le);
      p_filesz = readU64(buf, base + 32, le);
      p_memsz = readU64(buf, base + 40, le);
    } else {
      p_type = readU32(buf, base, le);
      p_offset = readU32(buf, base + 4, le);
      p_vaddr = readU32(buf, base + 8, le);
      p_filesz = readU32(buf, base + 16, le);
      p_memsz = readU32(buf, base + 20, le);
    }
    if (p_type === 1) { // PT_LOAD
      segs.push({ p_offset, p_vaddr, p_filesz, p_memsz });
    }
  }

  // Build a sparse byte image of the mapped memory.
  const mem = new Map();
  for (const s of segs) {
    for (let i = 0; i < s.p_memsz; i++) {
      const a = s.p_vaddr + i;
      mem.set(a, i < s.p_filesz ? buf[s.p_offset + i] : 0);
    }
  }

  function byteAt(a) {
    const v = mem.get(a);
    return v === undefined ? 0 : v;
  }

  // Emit complete 4-byte little-endian words at 4-byte-aligned addresses that
  // fall entirely within each segment's [p_vaddr, p_vaddr + p_memsz) range.
  for (const s of segs) {
    let a = s.p_vaddr;
    if (a % 4 !== 0) a += (4 - (a % 4));
    while (a + 4 <= s.p_vaddr + s.p_memsz) {
      const val = ((byteAt(a)) |
                   (byteAt(a + 1) << 8) |
                   (byteAt(a + 2) << 16) |
                   (byteAt(a + 3) << 24)) >>> 0;
      out[a] = val;
      a += 4;
    }
  }

  process.stdout.write(JSON.stringify(out) + '\n');
}

main();

